Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Frac {
    long long num, den;
};

pair<long long, long long> get_range(int x, int y, int b) {
    long long low = (long long)b * x / y;
    long long high = ((long long)b * x + y - 1) / y;
    return {low, high};
}

long long compute_gcd(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

void find_best_fraction(int x, int y, int n) {
    vector<Frac> candidates;
    for (int b = 1; b <= n; ++b) {
        auto range = get_range(x, y, b);
        candidates.push_back({range.first, b});
        candidates.push_back({range.second, b});
    }

    auto cmp = [&](Frac f1, Frac f2) {
        long long diff1 = abs((long long)x * f1.den * f2.den - f1.num * f2.den * y);
        long long diff2 = abs((long long)x * f1.den * f2.den - f2.num * f1.den * y);
        if (diff1 != diff2) return diff1 < diff2;
        if (f1.den != f2.den) return f1.den < f2.den;
        return f1.num < f2.num;
    };

    sort(candidates.begin(), candidates.end(), cmp);
    cout << candidates.front().num << "/" << candidates.front().den << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int x, y, n;
    cin >> x >> y >> n;
    find_best_fraction(x, y, n);
    return 0;
}
